// 1 item de entrada = resposta googleAds:search de UMA conta (customer_id).
// Saída: 1 item com o array `rows` pronto pro upsert em ad_metrics.
const rows = [];
for (let i = 0; i < items.length; i++) {
  const resp = items[i].json;
  const conta = $('Buscar contas Google Ads').itemMatching(i).json;
  for (const r of resp.results ?? []) {
    const m = r.metrics ?? {};
    rows.push({
      client_id: conta.client_id,
      account_external_id: String(conta.external_id),
      date: r.segments?.date,
      platform: 'google',
      campaign: r.campaign?.name ?? '(sem nome)',
      // Google Ads devolve custo em MICROS -> dividir por 1e6
      spend: Number(m.costMicros ?? 0) / 1_000_000,
      impressions: Number(m.impressions ?? 0),
      clicks: Number(m.clicks ?? 0),
      conversions: Math.round(Number(m.conversions ?? 0)),
      revenue: Number(m.conversionsValue ?? 0),
      // Parcela de impressões da rede de pesquisa (0..1; null quando não se aplica)
      search_impression_share: m.searchImpressionShare != null ? Number(m.searchImpressionShare) : null,
    });
  }
}
if (rows.length === 0) {
  return []; // nada a gravar -> encerra sem chamar o Supabase
}
return [{ json: { rows, total: rows.length } }];

