// 1 item = resposta googleAds:search (segments.conversion_action_*) de UMA conta.
// Enriquece cada linha com a ORIGEM da ação e mantém um lote separado por conta.
// O lote vazio é intencional: ele permite remover dados antigos quando o Google
// deixa de devolver uma conversão antes registrada na janela móvel.
const originByResource = {};
for (const it of $('GAQL Origem das ações').all()) {
  for (const r of it.json.results ?? []) {
    const ca = r.conversionAction;
    if (ca?.resourceName) {
      originByResource[ca.resourceName] = ca.origin ?? 'UNKNOWN';
    }
  }
}
const output = [];
for (let i = 0; i < items.length; i++) {
  const resp = items[i].json;
  if (resp?.error || resp?.errors || Number(resp?.statusCode ?? 200) >= 400) {
    throw new Error('A consulta de conversões do Google Ads falhou; a janela atual foi preservada.');
  }
  const conta = $('Buscar contas Google Ads').itemMatching(i).json;
  const rows = [];
  for (const r of resp.results ?? []) {
    const resource = r.segments?.conversionAction;
    rows.push({
      client_id: conta.client_id,
      account_external_id: String(conta.external_id),
      platform: 'google',
      date: r.segments?.date,
      campaign: r.campaign?.name ?? '(sem nome)',
      action_name: r.segments?.conversionActionName ?? '(sem nome)',
      action_category: r.segments?.conversionActionCategory ?? '',
      origin: (resource && originByResource[resource]) || 'UNKNOWN',
      conversions: Number(r.metrics?.conversions ?? 0),
      all_conversions: Number(r.metrics?.allConversions ?? r.metrics?.conversions ?? 0),
    });
  }
  output.push({
    json: {
      client_id: conta.client_id,
      account_external_id: String(conta.external_id),
      rows,
      total: rows.length,
    },
    pairedItem: { item: i },
  });
}
return output;

// Junta as respostas por conta, guarda as linhas brutas e coleta os IDs
// únicos de região (geoTargetConstants/NNN) pra traduzir em nome no próximo nó.
const raw = [];
const ids = new Set();
let customer = null;
for (let i = 0; i < items.length; i++) {
  const resp = items[i].json;
  const conta = $('Buscar contas Google Ads').itemMatching(i).json;
  if (!customer && conta.external_id) {
    customer = String(conta.external_id).replace(/-/g, '');
  }
  for (const r of resp.results ?? []) {
    const region = r.segments?.geoTargetCity;
    if (!region) continue; // linha sem região mapeada
    ids.add(region);
    raw.push({
      client_id: conta.client_id,
      account_external_id: String(conta.external_id),
      date: r.segments?.date,
      campaign: r.campaign?.name ?? '(sem nome)',
      region_id: region,
      impressions: Number(r.metrics?.impressions ?? 0),
      clicks: Number(r.metrics?.clicks ?? 0),
      spend: Number(r.metrics?.costMicros ?? 0) / 1_000_000,
      conversions: Number(r.metrics?.conversions ?? 0),
    });
  }
}
if (raw.length === 0 || !customer) {
  return []; // nada a gravar
}
const list = [...ids].map((id) => `'${id}'`).join(', ');
const query = `SELECT geo_target_constant.resource_name, geo_target_constant.name FROM geo_target_constant WHERE geo_target_constant.resource_name IN (${list})`;
return [{ json: { customer, query, raw } }];

// Traduz region_id -> nome e agrega por cliente/conta/dia/campanha/região.
const prep = $('Preparar consulta de regiões').first().json;
const names = {};
for (const item of items) {
  for (const r of item.json.results ?? []) {
    const g = r.geoTargetConstant ?? {};
    if (g.resourceName) names[g.resourceName] = g.name ?? g.resourceName;
  }
}
const map = new Map();
for (const row of prep.raw ?? []) {
  const region = names[row.region_id] ?? String(row.region_id).replace('geoTargetConstants/', 'região ');
  const key = [row.client_id, row.account_external_id, row.date, row.campaign, region].join('|');
  const acc = map.get(key) ?? {
    client_id: row.client_id,
    account_external_id: row.account_external_id,
    platform: 'google',
    date: row.date,
    campaign: row.campaign,
    region,
    impressions: 0,
    clicks: 0,
    spend: 0,
    conversions: 0,
  };
  acc.impressions += row.impressions;
  acc.clicks += row.clicks;
  acc.spend += row.spend;
  acc.conversions += row.conversions;
  map.set(key, acc);
}
const rows = [...map.values()].map((r) => ({
  ...r,
  spend: Math.round(r.spend * 100) / 100,
}));
if (rows.length === 0) {
  return []; // nada a gravar
}
return [{ json: { rows, total: rows.length } }];

const rows = [];
for (let i = 0; i < items.length; i++) {
  const resp = items[i].json;
  const conta = $('Buscar contas Google Ads').itemMatching(i).json;
  for (const r of resp.results ?? []) {
    const m = r.metrics ?? {};
    rows.push({
      client_id: conta.client_id,
      account_external_id: String(conta.external_id),
      platform: 'google',
      date: r.segments?.date,
      campaign: r.campaign?.name ?? '(sem nome)',
      search_term: r.searchTermView?.searchTerm ?? '(desconhecido)',
      impressions: Number(m.impressions ?? 0),
      clicks: Number(m.clicks ?? 0),
      spend: Number(m.costMicros ?? 0) / 1_000_000,
      conversions: Number(m.conversions ?? 0),
    });
  }
}
if (rows.length === 0) return [];
// Upsert em lotes: search terms geram muitas linhas; um POST unico estoura.
const CHUNK = 200;
const out = [];
for (let j = 0; j < rows.length; j += CHUNK) {
  out.push({ json: { rows: rows.slice(j, j + CHUNK), total: rows.length } });
}
return out;

