  }
}
if (rows.length === 0) return [];
return [{ json: { rows, total: rows.length } }];

// 1 item = resposta de account_budget de UMA conta.
const out = [];
for (let i = 0; i < items.length; i++) {
  const conta = $('Buscar contas Google Ads').itemMatching(i).json;
  const results = items[i].json?.results ?? [];
  if (results.length === 0) continue; // conta sem orcamento de conta (faturamento mensal)
  let limite = 0;
  let servido = 0;
  for (const r of results) {
    const b = r.accountBudget ?? {};
    limite += Number(b.adjustedSpendingLimitMicros ?? b.approvedSpendingLimitMicros ?? 0) / 1e6;
    servido += Number(b.amountServedMicros ?? 0) / 1e6;
  }
  out.push({
    json: {
      external_id: String(conta.external_id),
      balance_limit: Number(limite.toFixed(2)),
      balance_spent: Number(servido.toFixed(2)),
      balance_available: Number((limite - servido).toFixed(2)),
    },
  });
}
return out;
